blocks.code:
table inet filter {
  chain forward {
    type filter hook forward priority 0; policy drop;
    ct state established,related accept
    # allow only the published service, only from the partner range
    ip saddr 198.51.100.0/24 ip daddr 10.10.0.20 tcp dport 443 ct status dnat accept
    # outbound from the LAN
    iifname "lan0" oifname "wan0" accept
  }
}
table ip nat {
  chain prerouting {
    type nat hook prerouting priority -100;
    iifname "wan0" ip saddr 198.51.100.0/24 tcp dport 8443 dnat to 10.10.0.20:443
  }
  chain postrouting {
    type nat hook postrouting priority 100;
    oifname "wan0" ip saddr 10.10.0.0/24 masquerade
  }
}

lines.output:
table ip nat {
  chain prerouting {
    iifname "wan0" ip saddr 198.51.100.0/24 tcp dport 8443 dnat to 10.10.0.20:443
  }
}

